export const ENTRY_ID = 'daroyan/entry';
export const ENTRY_FILE = 'entry.ts';
/**
 * Order matters: routes register in this order, and Hono runs the first
 * matching handler. `ALL` is last so a file exporting both `GET` and `ALL`
 * serves GET from `GET` and every other verb from `ALL`.
 */
export const HTTP_METHODS = [
  'GET',
  'POST',
  'PUT',
  'PATCH',
  'DELETE',
  'OPTIONS',
  'ALL',
] as const;
export const GENERATED_NOTICE =
  '// Generated by Daroyan (format 1). Do not edit.';
/**
 * Every top-level name Daroyan may own inside its generated directory,
 * including the transient lock. Used to tell an existing generated directory
 * apart from a directory that holds someone else's files, so the check cannot
 * be fooled by a generation that is still in progress.
 */
export const GENERATED_ENTRIES = [
  '.lock',
  'client.ts',
  'daroyan.d.ts',
  'modules.d.ts',
  ENTRY_FILE,
  'manifest.json',
  'rpc.ts',
  'types',
] as const;
